package dev.mcpmcp.forge;
import com.google.gson.*;import dev.mcpmcp.core.*;
import net.minecraft.client.Minecraft;import net.minecraft.network.*;import net.minecraft.network.protocol.*;import net.minecraft.network.protocol.game.*;
import net.minecraft.resources.ResourceLocation;import net.minecraft.nbt.*;import net.minecraft.core.*;import net.minecraft.world.item.*;
import io.netty.channel.*;import io.netty.buffer.Unpooled;
import java.util.*;import java.lang.reflect.*;
/** Version-scoped codec and bounded metadata capture over the existing connection. */
public final class PacketService {
 private static final ArrayDeque<JsonObject> capture=new ArrayDeque<>();private static volatile boolean capturing;private static String filter="";private static long sequence;private static Connection attached;
 public static synchronized void record(Object value,String direction){if(!capturing||!(value instanceof Packet<?> packet))return;String cls=packet.getClass().getName();if(!cls.toLowerCase(Locale.ROOT).contains(filter))return;JsonObject e=Jsons.obj("sequence",++sequence,"time",System.currentTimeMillis(),"direction",direction,"class",cls);capture.add(e);while(capture.size()>512)capture.removeFirst();}
 public static void attach(){Minecraft mc=Minecraft.getInstance();if(mc.getConnection()==null)return;Connection c=mc.getConnection().getConnection();if(c==attached)return;attached=c;Channel channel=c.channel();if(channel==null)return;channel.eventLoop().execute(()->{if(channel.pipeline().get("mcpmcp_observer")==null)channel.pipeline().addBefore("packet_handler","mcpmcp_observer",new ChannelDuplexHandler(){public void channelRead(ChannelHandlerContext ctx,Object msg)throws Exception{record(msg,"S2C");super.channelRead(ctx,msg);}public void write(ChannelHandlerContext ctx,Object msg,ChannelPromise promise)throws Exception{if(msg instanceof ServerboundPlayerActionPacket p&&p.getAction()==ServerboundPlayerActionPacket.Action.RELEASE_USE_ITEM&&Actions.suppressUseRelease()){promise.setSuccess();return;}record(msg,"C2S");super.write(ctx,msg,promise);}});});}
 public static void connectionChanged(){attached=null;capturing=false;}
 private static JsonArray directory(String query,String direction){JsonArray a=new JsonArray();for(PacketFlow f:PacketFlow.values()){String dir=f==PacketFlow.SERVERBOUND?"C2S":"S2C";if(!direction.equals("all")&&!direction.equals(dir))continue;ConnectionProtocol.PLAY.getPacketsByIds(f).forEach((id,cls)->{if(cls.getName().toLowerCase(Locale.ROOT).contains(query))a.add(Jsons.obj("id","vanilla:"+dir+":"+id,"class",cls.getName(),"direction",dir,"channel","minecraft:play","discriminator",id));});}for(ModPacketCatalog.Message m:ModPacketCatalog.entries()){String dir=m.direction().equals("PLAY_TO_SERVER")?"C2S":m.direction().equals("PLAY_TO_CLIENT")?"S2C":"unknown";if(!direction.equals("all")&&!direction.equals(dir))continue;if((m.type().getName()+" "+m.channel()).toLowerCase(Locale.ROOT).contains(query))a.add(Jsons.obj("id","forge:"+m.channel()+":"+m.id(),"class",m.type().getName(),"channel",m.channel(),"discriminator",m.id(),"direction",dir));}return a;}
 public static JsonObject read(String kind,JsonObject args){if(kind.equals("packet_capture")){JsonArray a=new JsonArray();long after=(long)Jsons.number(args,"after",0);int limit=Math.max(1,Math.min(200,Jsons.integer(args,"limit",50)));synchronized(PacketService.class){for(JsonObject e:capture)if(e.get("sequence").getAsLong()>after&&a.size()<limit)a.add(e.deepCopy());}return Jsons.obj("entries",a,"capturing",capturing,"source","existing_connection_metadata","payload_capture",false);}
  String query=Jsons.str(args,"query","").toLowerCase(Locale.ROOT);JsonArray all=directory(query,Jsons.str(args,"direction","all"));if(kind.equals("packet")){String wanted=Jsons.str(args,"id","");for(JsonElement v:directory("","all")){JsonObject row=v.getAsJsonObject();if(row.get("id").getAsString().equals(wanted)||row.get("class").getAsString().equals(wanted)){try{Class<?> c=Class.forName(row.get("class").getAsString());JsonArray constructors=new JsonArray();for(Constructor<?> ctor:c.getConstructors()){JsonArray types=new JsonArray();for(Class<?> t:ctor.getParameterTypes())types.add(t.getName());constructors.add(types);}row.add("constructors",constructors);return row;}catch(Exception e){return Jsons.error("packet_class_unavailable");}}}return Jsons.error("unknown_packet");}
  int offset=Math.max(0,Jsons.integer(args,"offset",0)),limit=Math.max(1,Math.min(500,Jsons.integer(args,"limit",50)));JsonArray page=new JsonArray();for(int i=offset;i<Math.min(all.size(),offset+limit);i++)page.add(all.get(i));return Jsons.obj("entries",page,"total",all.size(),"next_offset",offset+page.size(),"has_more",offset+page.size()<all.size(),"coverage_complete",false,"scope","vanilla_PLAY_and_discovered_forge_channels","coverage",ModPacketCatalog.coverage());
 }
 public static JsonObject execute(String action,JsonObject args){switch(action){case "packet.capture_start":{filter=Jsons.str(args,"query","").toLowerCase(Locale.ROOT);capturing=true;attach();return Jsons.obj("observed_success",true,"capturing",true);}case "packet.capture_stop":{capturing=false;return Jsons.obj("observed_success",true,"capturing",false);}case "packet.send":return send(args);default:return Jsons.error("unknown_packet_action");}}
 public static void sendPacket(Packet<?> p){Minecraft mc=Minecraft.getInstance();if(mc.getConnection()==null)throw new IllegalArgumentException("not_connected");mc.getConnection().send(p);}
 public static JsonObject send(JsonObject a){try{String name=Jsons.str(a,"packet_class","");if(!name.matches("[A-Za-z_$][A-Za-z0-9_$.]{1,255}"))return Jsons.error("invalid_packet_class");String required=PacketPolicy.permission(name);if(!Policy.allowed(Runtime.config().mode,Runtime.config().transport,"packet",required))return Jsons.obj("error","packet_policy_denied","required_permission",required);Class<?> cls=Class.forName(name,false,PacketService.class.getClassLoader());boolean vanilla=ConnectionProtocol.PLAY.getPacketsByIds(PacketFlow.SERVERBOUND).containsValue(cls);ModPacketCatalog.Message mod=vanilla?null:ModPacketCatalog.find(cls,Jsons.str(a,"channel",""));if(!vanilla&&(mod==null||!mod.direction().equals("PLAY_TO_SERVER")))return Jsons.error("packet_not_discovered_c2s");if((name.contains("Command")||name.contains("ChatPacket"))&&!Runtime.config().mode.contains("CHEAT"))return Jsons.error("chat_command_packet_requires_explicit_chat_or_cheat_path");String mode=Jsons.str(a,"mode","constructor");Object packet;
   if(mode.equals("wire")){int id=-1;for(var e:ConnectionProtocol.PLAY.getPacketsByIds(PacketFlow.SERVERBOUND).int2ObjectEntrySet())if(e.getValue()==cls)id=e.getIntKey();if(id<0)return Jsons.error("wire_requires_registered_vanilla_c2s");FriendlyByteBuf buf=new FriendlyByteBuf(Unpooled.buffer());try{for(JsonElement x:Jsons.array(a,"fields")){JsonObject f=x.getAsJsonObject();encode(buf,Jsons.str(f,"type",""),f.get("value"));if(buf.writerIndex()>16384)throw new IllegalArgumentException("wire_budget");}packet=ConnectionProtocol.PLAY.createPacket(PacketFlow.SERVERBOUND,id,buf);if(packet==null||packet.getClass()!=cls||buf.readableBytes()!=0)return Jsons.error("wire_layout_mismatch");}finally{buf.release();}}
   else if(mode.equals("constructor")){JsonArray signature=Jsons.array(a,"signature"),values=Jsons.array(a,"values");if(signature.size()!=values.size()||signature.size()>16)throw new IllegalArgumentException("constructor_arity");Constructor<?> ctor=null;for(Constructor<?> c:cls.getConstructors()){Class<?>[] types=c.getParameterTypes();if(types.length!=signature.size())continue;boolean match=true;for(int i=0;i<types.length;i++)match&=types[i].getName().equals(signature.get(i).getAsString());if(match){ctor=c;break;}}if(ctor==null)return Jsons.error("constructor_not_found");Object[] parameters=new Object[values.size()];for(int i=0;i<parameters.length;i++)parameters[i]=convert(values.get(i),ctor.getParameterTypes()[i]);packet=ctor.newInstance(parameters);}
   else return Jsons.error("invalid_packet_mode");
   if(packet instanceof Packet<?> p){if(ConnectionProtocol.getProtocolForPacket(p)!=ConnectionProtocol.PLAY||ConnectionProtocol.PLAY.getPacketId(PacketFlow.SERVERBOUND,p)<0)return Jsons.error("only_play_c2s_allowed");sendPacket(p);}else{if(mod==null)return Jsons.error("mod_channel_unavailable");mod.sender().sendToServer(packet);}return Jsons.obj("delivery","submitted","packet_class",name,"server_acceptance_confirmed",false);
  }catch(Exception|LinkageError e){return Jsons.obj("error","packet_send_failed","reason",e.getClass().getSimpleName()+": "+Objects.toString(e.getMessage(),""));}}
 private static Object convert(JsonElement e,Class<?> type)throws Exception{if(type==String.class)return e.getAsString();if(type==int.class||type==Integer.class)return integral(e,Integer.MIN_VALUE,Integer.MAX_VALUE).intValue();if(type==long.class||type==Long.class)return integral(e,Long.MIN_VALUE,Long.MAX_VALUE);if(type==short.class)return integral(e,Short.MIN_VALUE,Short.MAX_VALUE).shortValue();if(type==byte.class)return integral(e,Byte.MIN_VALUE,Byte.MAX_VALUE).byteValue();if(type==boolean.class){if(!e.isJsonPrimitive()||!e.getAsJsonPrimitive().isBoolean())throw new IllegalArgumentException("bool_required");return e.getAsBoolean();}if(type==float.class||type==double.class){double n=e.getAsDouble();if(!Double.isFinite(n))throw new IllegalArgumentException("finite_required");if(type==float.class)return (float)n;return n;}if(type==UUID.class)return UUID.fromString(e.getAsString());if(type==ResourceLocation.class)return new ResourceLocation(e.getAsString());if(type==BlockPos.class){JsonObject p=e.getAsJsonObject();return new BlockPos(Jsons.integer(p,"x",0),Jsons.integer(p,"y",0),Jsons.integer(p,"z",0));}if(type==CompoundTag.class)return TagParser.parseTag(e.getAsString());if(type==ItemStack.class){JsonObject o=e.getAsJsonObject();ResourceLocation id=new ResourceLocation(Jsons.str(o,"item_id","minecraft:air"));if(!net.minecraft.core.registries.BuiltInRegistries.ITEM.containsKey(id))throw new IllegalArgumentException("unknown_item");ItemStack stack=new ItemStack(net.minecraft.core.registries.BuiltInRegistries.ITEM.get(id),Math.max(0,Math.min(64,Jsons.integer(o,"count",1))));if(o.has("nbt"))stack.setTag(TagParser.parseTag(o.get("nbt").getAsString()));return stack;}if(type.isEnum()){for(Object v:type.getEnumConstants())if(((Enum<?>)v).name().equals(e.getAsString()))return v;}throw new IllegalArgumentException("unsupported_constructor_type_"+type.getName());}
 private static Long integral(JsonElement e,long min,long max){if(e==null||!e.isJsonPrimitive()||!e.getAsJsonPrimitive().isNumber())throw new IllegalArgumentException("integer_required");long n;try{n=e.getAsBigDecimal().longValueExact();}catch(ArithmeticException ex){throw new IllegalArgumentException("integer_out_of_range");}if(n<min||n>max)throw new IllegalArgumentException("integer_out_of_range");return n;}
 private static void encode(FriendlyByteBuf b,String t,JsonElement v)throws Exception{switch(t){case "byte"->b.writeByte(integral(v,-128,127).intValue());case "short"->b.writeShort(integral(v,-32768,32767).intValue());case "int"->b.writeInt(integral(v,Integer.MIN_VALUE,Integer.MAX_VALUE).intValue());case "varint"->b.writeVarInt(integral(v,Integer.MIN_VALUE,Integer.MAX_VALUE).intValue());case "long"->b.writeLong(integral(v,Long.MIN_VALUE,Long.MAX_VALUE));case "varlong"->b.writeVarLong(integral(v,Long.MIN_VALUE,Long.MAX_VALUE));case "boolean"->b.writeBoolean((Boolean)convert(v,boolean.class));case "float"->b.writeFloat((Float)convert(v,float.class));case "double"->b.writeDouble((Double)convert(v,double.class));case "utf"->b.writeUtf(v.getAsString(),4096);case "uuid"->b.writeUUID((UUID)convert(v,UUID.class));case "block_pos"->b.writeBlockPos((BlockPos)convert(v,BlockPos.class));case "item_stack"->b.writeItem((ItemStack)convert(v,ItemStack.class));case "nbt"->b.writeNbt((CompoundTag)convert(v,CompoundTag.class));default->throw new IllegalArgumentException("unsupported_wire_type");}}
}
